    {
        long start = System.Diagnostics.Stopwatch.GetTimestamp();
        int value = RemainingHealingPotentialDiagnosticCore(snapshot, certifiedOnly);
        LatePlanProofDiagnosticsForResearch.Record(value, System.Diagnostics.Stopwatch.GetTimestamp() - start);
        return value;
    }

    private int RemainingHealingPotentialDiagnosticCore(SimulationSnapshot snapshot, bool certifiedOnly)
    {'''
