internal static class LatePlanProofDiagnosticsForResearch
{
    internal static long Calls, Unknown, Ticks;
    internal static double ElapsedMilliseconds => Ticks * 1000d / System.Diagnostics.Stopwatch.Frequency;
    internal static void Record(int value, long ticks)
    {
        Interlocked.Increment(ref Calls);
